with valid as (select *, lower(page) as page_lower, coalesce(page, 'OTHER') as resolved_page from web_events where event_time >= '2023-05-01' and page is not null), gaps as (select *, case when lag(event_time) over (partition by event_type order by event_time, id) is null or event_time > lag(event_time) over (partition by event_type order by event_time, id) + interval '60' day then 1 else 0 end as is_new_session from valid), sessions_web_events as (select id, session_id, event_type, event_time, sum(is_new_session) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as session_id_2 from gaps) select event_type, approx_percentile(session_id_2, array(0.25, 0.5, 0.75)) as session_id_2_quartiles, round(sum(session_id_2) / nullif(count(case when event_type = 'click' then 1 end), 0), 2) as session_id_2_per_click, size(collect_set(event_type)) as num_event_types, grouping_id() as gid from sessions_web_events group by cube (event_type)
